CREATE OR REPLACE FUNCTION public.atlas_assert_service_role()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_legacy_role text := coalesce(current_setting('request.jwt.claim.role', true), '');
  v_claims_text text := coalesce(current_setting('request.jwt.claims', true), '');
  v_claims_role text := '';
begin
  if v_claims_text <> '' then
    begin
      v_claims_role := coalesce((v_claims_text::jsonb)->>'role', '');
    exception when others then
      v_claims_role := '';
    end;
  end if;

  if session_user in ('postgres', 'service_role')
     or v_legacy_role = 'service_role'
     or v_claims_role = 'service_role' then
    return;
  end if;

  raise exception 'Atlas Control Plane mutations require server-side service role access'
    using errcode = '42501';
end;
$function$

CREATE OR REPLACE FUNCTION public.atlas_require_source_evidence(p_sources jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(p_sources) <> 'array' or jsonb_array_length(p_sources) < 1 then
    raise exception 'At least one source evidence record is required';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_sources) s
    where nullif(btrim(coalesce(s->>'source_url', '')), '') is null
       or nullif(btrim(coalesce(s->>'source_name', '')), '') is null
       or coalesce((s->>'is_official')::boolean, false) is not true
  ) then
    raise exception 'Each intake source must include source_name, source_url, and is_official=true';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_atlas_control_plane_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
